  // 3. ไปรษณียภัณฑ์ไม่มีจ่าหน้า (Unaddressed Mail / Advertising Mail - Admail)
  // 4. พัสดุ (พัสดุไปรษณีย์ P + เปรียบเทียบ eCo-Post / EMS ในประเทศ / EMS Jumbo)
  // =========================================================================
