        indemnity: "🛡️ EMS ปกติ: ชดใช้ตามจริงไม่เกิน 2,000 บาท/ชิ้น (ยื่นขอสอบสวนภายใน 4 เดือน) | 🛡️ ซื้อรับประกันเพิ่ม (EMS Insurance): คุ้มครองสูงสุด 50,000 บาท (เช่น ประกัน 500บ.=20บ., 1,000บ.=25บ., 5,000บ.=65บ., 10,000บ.=115บ., 20,000บ.=215บ., 30,000บ.=415บ., 40,000บ.=615บ., 50,000บ.=815บ.)",
