          "🚨 จุดตาย #2 【ต้องบันทึกที่อยู่ผู้รับใน CA POS ให้ครบถ้วนทุกช่อง! (ปณท รป.(รฝ.2)/718 ลว. 14 ก.ค. 69)】: บริษัท ไปรษณีย์ไทยดิสทริบิวชั่น จำกัด (ปณด) ต้องใช้ข้อมูล บ้านเลขที่ ตำบล อำเภอ และจังหวัดของผู้รับ ในการคำนวณระวางรถขนส่ง ห้ามคีย์ข้ามหรือย่อที่อยู่ผู้รับในระบบ CA POS เด็ดขาด!",
          "🚨 จุดตาย #3 【กฎการคิดค่าส่งอุปกรณ์ส่วนควบแยกกล่อง & ค่าบริการส่วนเพิ่ม】: (1) หากสินค้าสำเร็จรูปมีส่วนควบที่ต้องแยกส่งเป็น 2 กล่อง (เช่น คอมพิวเตอร์ จอ+CPU หรือ แอร์ คอยล์ร้อน+คอยล์เย็น) ชิ้นแรกคิดราคาเต็ม ส่วนชิ้นที่ 2 คิดเพียง 'กึ่งหนึ่ง (50%)' ของราคาหลัก! | (2) รถจักรยานยนต์ขนาด 125 CC ให้เรียกเก็บในอัตรา 'ไม่เกิน 150 CC' | (3) รถสามล้อเครื่อง / ATV / พ่วงข้าง / พารามอเตอร์ รับฝากเฉพาะ 'ศป. ถึง ศป.' เท่านั้น!",
          "🚨 จุดตาย #4 【ค่าบริการรับฝาก ณ ที่อยู่ผู้ฝาก / นำจ่าย ณ ที่อยู่ผู้รับ (60–500 บ.) และค่าเก็บรักษา】: หากลูกค้าให้ไปรับที่บ้าน หรือให้นำจ่ายถึงบ้าน (ไม่รวมกรณีจ่าหน้ารอจ่าย ณ ปณ.) มีค่าบริการเพิ่มตามขั้นค่าส่งปกติ (ค่าส่ง ≤300บ. เก็บเพิ่ม 60บ. | ≤500บ. เก็บ 90บ. | ≤1,000บ. เก็บ 180บ. | ≤1,500บ. เก็บ 250บ. | ≤2,000บ. เก็บ 300บ. | ≤2,500บ. เก็บ 350บ. | ≤3,000บ. เก็บ 400บ. | ≤5,000บ. เก็บ 450บ. | >5,000บ. เก็บ 500บ.) และกรณีผู้รับมารับของที่ ปณ.ปลายทางช้าเกิน 7 วัน เก็บค่าเก็บรักษา 25 บาท/ชิ้น/วัน!"
